 await check('11 same product in two dimensions keeps exact source identity and full mixed-line rollback',async()=>{const order=await must('/api/orders','POST',{order_number:'COMPOSER-TWO-'+key(),manager_id:sale.id,status:'processing',items:[{id:key(),product_id:product,quantity:3,color:'Trắng',dimensions:'140x200cm'},{id:key(),product_id:product,quantity:5,color:'Xanh',dimensions:'180x200cm'}]}),original=await source(order.id);assert.equal(original.items.length,2);assert.notEqual(original.items[0].source_line_key,original.items[1].source_line_key);assert.deepEqual(original.items.map(x=>x.dimensions),['140x200cm','180x200cm']);const req=await must('/api/production-sales/requests','POST',{order_id:order.id,lines:original.items.map(x=>({source_line_key:x.source_line_key,quantity:x.ordered_quantity})),idempotency_key:key()},sale.token);await must('/api/production-sales/requests/'+req.id+'/review','POST',{target_status:'ACCEPTED',reason:'Two dimensions synthetic acceptance',idempotency_key:key()});const f={order,original,req},body=command(f);body.lines=req.lines.map((line,index)=>({request_line_id:line.id,quantity:index?'4':'2',cutting_plan:{reason:'Separate material plan for exact source dimension',lines:materialLines()}}));const broken=structuredClone(body);broken.lines[1].cutting_plan.lines[1].warehouse_id=key();await rejectedUnchanged(f,broken);const r=await allocate(f,body);assert.equal(r.status,201,JSON.stringify(r));assert.equal(r.body.orders.length,2);for(const [index,created]of r.body.orders.entries()){await verifyDraft({orders:[created]},index?'4':'2');const item=(await pool.query('select * from local_production_order_items where id=$1',[created.order_item_id])).rows[0],requestLine=req.lines.find(x=>x.id===created.request_line_id);assert.equal(item.sales_request_line_id,requestLine.id);assert.equal(item.source_order_item_key,requestLine.source_line_key);assert.equal(item.dimensions,requestLine.source_line_snapshot.dimensions);}await untouchedAccounting();});
 const directFixture=async(quantity='5')=>{const order=await must('/api/orders','POST',{order_number:'DIRECT-'+key(),manager_id:sale.id,status:'processing',items:[{id:key(),product_id:product,quantity,color:'Trắng',dimensions:'160x200cm'}]});return{order,original:await source(order.id)};};
 const directBody=(f,quantity='2')=>({idempotency_key:key(),planned_start_date:'2026-11-02',lines:[{source_line_key:f.original.items[0].source_line_key,quantity,cutting_plan:{reason:'Direct CRM plan',lines:materialLines()}}]});
 const direct=(f,body,auth=token)=>call('/api/production/source-orders/'+f.order.id+'/create','POST',body,auth);
 const allDirectState=async()=>({business:await snapshot(),source:(await pool.query('select to_jsonb(r)v from local_production_sales_requests r order by id')).rows,lines:(await pool.query('select to_jsonb(r)v from local_production_sales_request_lines r order by id')).rows,receipts:(await pool.query('select to_jsonb(r)v from local_production_workflow_requests r order by idempotency_key')).rows});
 await check('12 direct CRM order creates atomic draft without submit/review, snapshot dimensions and replay preserved',async()=>{const f=await directFixture(),body=directBody(f),r=await direct(f,body);assert.equal(r.status,201,JSON.stringify(r));await verifyDraft(r.body);const request=(await pool.query('select * from local_production_sales_requests where id=$1',[r.body.request_id])).rows[0];assert.equal(request.status,'ACCEPTED');assert.equal(request.reviewed_by,null);assert.equal(request.reviewed_at,null);assert.ok((await pool.query("select 1 from local_production_sales_events where request_id=$1 and action='DIRECT_CREATE'",[request.id])).rows[0]);const item=(await pool.query('select * from local_production_order_items where id=$1',[r.body.orders[0].order_item_id])).rows[0];assert.equal(item.dimensions,'160x200cm');const state=await allDirectState(),replay=await direct(f,body);assert.equal(replay.status,200,JSON.stringify(replay));assert.equal(replay.body.orders[0].id,r.body.orders[0].id);assert.deepEqual(await allDirectState(),state);const changed=structuredClone(body);changed.lines[0].quantity='1';assert.equal((await direct(f,changed)).status,409);assert.deepEqual(await allDirectState(),state);});
 await check('13 direct pending reservation reused immediately, no independent reviewer fabricated',async()=>{const f=await directFixture(),pending=await must('/api/production-sales/requests','POST',{order_id:f.order.id,idempotency_key:key(),lines:[{source_line_key:f.original.items[0].source_line_key,quantity:'5'}]},sale.token),r=await direct(f,directBody(f));assert.equal(r.status,201,JSON.stringify(r));assert.equal(r.body.request_id,pending.id);await verifyDraft(r.body);const saved=(await pool.query('select * from local_production_sales_requests where id=$1',[pending.id])).rows[0];assert.equal(saved.status,'ACCEPTED');assert.equal(saved.reviewed_by,null);assert.equal(saved.reviewed_at,null);});
 await check('14 direct invalid material rolls back internal linkage, source lines, audit and receipt',async()=>{const f=await directFixture(),body=directBody(f);body.lines[0].cutting_plan.lines[1].inventory_item_id=key();const state=await allDirectState(),r=await direct(f,body);assert.ok(r.status>=400,JSON.stringify(r));assert.deepEqual(await allDirectState(),state);});
 await check('15 direct concurrent last remaining quantity and legacy reservations never overallocate',async()=>{const f=await directFixture('3'),responses=await Promise.all([direct(f,directBody(f)),direct(f,directBody(f))]);assert.equal(responses.filter(r=>r.status<300).length,1,JSON.stringify(responses));const total=(await pool.query('select sum(a.quantity) n from local_production_sales_allocations a join local_production_sales_request_lines l on l.id=a.request_line_id join local_production_sales_requests r on r.id=l.request_id where r.order_id=$1',[f.order.id])).rows[0].n;assert.equal(Number(total),2);});
